-- The catalog queries of the gate programs of the drivers: psycopg, node-postgres, pgx and asyncpg. A driver has no describe command, so its gate program runs these queries and writes the values as the driver gives them. Then it writes the columns that the driver describes for a query of each table. Each line that does not start with -- is one query.
SELECT n.nspname, pg_get_userbyid(n.nspowner) AS owner, obj_description(n.oid, 'pg_namespace') AS comment FROM pg_namespace n WHERE n.nspname = 'gate'
SELECT c.relname, c.relkind, c.relhasindex, c.relchecks, c.relnatts, obj_description(c.oid, 'pg_class') AS comment FROM pg_class c WHERE c.relnamespace = 'gate'::regnamespace ORDER BY c.relname
SELECT c.relname, a.attnum, a.attname, a.atttypid::regtype, a.atttypmod, format_type(a.atttypid, a.atttypmod), a.attnotnull, a.atthasdef, pg_get_expr(d.adbin, d.adrelid) AS default, col_description(c.oid, a.attnum) AS comment FROM pg_class c JOIN pg_attribute a ON a.attrelid = c.oid LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE c.relnamespace = 'gate'::regnamespace AND c.relkind IN ('r', 'v') AND a.attnum > 0 AND NOT a.attisdropped ORDER BY c.relname, a.attnum
SELECT t.typname, t.typtype, t.typcategory, t.typlen, format_type(t.oid, NULL), t.typrelid::regclass, t.typelem::regtype, t.typarray::regtype FROM pg_type t WHERE t.typnamespace = 'gate'::regnamespace ORDER BY t.typname
SELECT i.indrelid::regclass, i.indexrelid::regclass, i.indnatts, i.indnkeyatts, i.indisunique, i.indisprimary, i.indkey, i.indoption, am.amname, pg_get_indexdef(i.indexrelid), pg_get_expr(i.indpred, i.indrelid) AS predicate FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_am am ON am.oid = c.relam WHERE c.relnamespace = 'gate'::regnamespace ORDER BY i.indrelid::regclass::text, i.indexrelid::regclass::text
SELECT conrelid::regclass, conname, contype, condeferrable, condeferred, convalidated, conkey, confrelid::regclass, confkey, confupdtype, confdeltype, confmatchtype, conindid::regclass, pg_get_constraintdef(oid), pg_get_constraintdef(oid, true) FROM pg_constraint WHERE connamespace = 'gate'::regnamespace ORDER BY conrelid::regclass::text, conname
SELECT s.seqrelid::regclass, s.seqtypid::regtype, s.seqstart, s.seqincrement, s.seqmax, s.seqmin, s.seqcache, s.seqcycle, pg_get_serial_sequence(d.refobjid::regclass::text, a.attname) FROM pg_sequence s JOIN pg_depend d ON d.objid = s.seqrelid AND d.classid = 'pg_class'::regclass AND d.deptype = 'a' JOIN pg_attribute a ON a.attrelid = d.refobjid AND a.attnum = d.refobjsubid WHERE s.seqrelid::regclass::text LIKE 'gate.%' ORDER BY s.seqrelid::regclass::text
SELECT pg_get_viewdef('gate.customer_orders'::regclass, true)
SELECT table_name, column_name, ordinal_position, column_default, is_nullable, data_type, character_maximum_length, numeric_precision, numeric_scale, datetime_precision, udt_name FROM information_schema.columns WHERE table_schema = 'gate' ORDER BY table_name, ordinal_position
SELECT tc.table_name, tc.constraint_name, tc.constraint_type, kcu.column_name, kcu.ordinal_position FROM information_schema.table_constraints tc LEFT JOIN information_schema.key_column_usage kcu ON kcu.constraint_schema = tc.constraint_schema AND kcu.constraint_name = tc.constraint_name WHERE tc.table_schema = 'gate' ORDER BY 1, 2, 5
